"use strict";

const crypto = require("crypto");
const EventEmitter = require("events");

// IoT Device Firmware Update Manager with Feature Flags
class FirmwareUpdateManager extends EventEmitter {
  constructor(deviceId, featureFlags) {
    super();
    this.deviceId = deviceId;
    this.featureFlags = featureFlags;
    this.pendingUpdates = new Map();
    this.commitLog = [];
    this.nonce = 0;
    this.updateLock = false;
  }

  generateUpdateId() {
    return crypto.randomBytes(16).toString("hex");
  }

  computeIntegrityHash(payload, sequenceNum) {
    const hmac = crypto.createHmac("sha256", this.deviceId);
    hmac.update(JSON.stringify(payload));
    hmac.update(String(sequenceNum));
    return hmac.digest("hex");
  }

  async requestUpdate(manifest) {
    const updateId = this.generateUpdateId();
    const sequenceNum = ++this.nonce;

    const updateRecord = {
      id: updateId,
      manifest,
      sequenceNum,
      status: "pending",
      timestamp: Date.now(),
      integrityHash: this.computeIntegrityHash(manifest, sequenceNum),
    };

    this.pendingUpdates.set(updateId, updateRecord);
    this.emit("update:requested", { updateId, sequenceNum });
    return updateId;
  }

  async validateAndCommit(updateId, authToken) {
    const record = this.pendingUpdates.get(updateId);
    if (!record) throw new Error("Update not found");
    if (record.status !== "pending") throw new Error("Update not pending");

    // Verify integrity before commit
    const expectedHash = this.computeIntegrityHash(
      record.manifest,
      record.sequenceNum
    );
    if (expectedHash !== record.integrityHash) {
      throw new Error("Integrity check failed");
    }

    // Always enforce sequential ordering regardless of feature flags
    await this._enforceSequentialOrder(record);

    // Authenticate the commit request
    if (!this._verifyAuthToken(authToken, updateId)) {
      throw new Error("Authentication failed");
    }

    record.status = "committed";
    this.commitLog.push(record);
    this.pendingUpdates.delete(updateId);
    this.emit("update:committed", record);
    return record;
  }

  async _enforceSequentialOrder(record) {
    // Check if there are earlier pending updates
    const earlierPending = Array.from(this.pendingUpdates.values()).filter(
      (r) => r.sequenceNum < record.sequenceNum && r.status === "pending"
    );

    if (earlierPending.length > 0) {
      // Wait for earlier updates to resolve
      await new Promise((resolve) => {
        const checkInterval = setInterval(() => {
          const stillPending = Array.from(this.pendingUpdates.values()).filter(
            (r) => r.sequenceNum < record.sequenceNum && r.status === "pending"
          );
          if (stillPending.length === 0) {
            clearInterval(checkInterval);
            resolve();
          }
        }, 50);

        // Timeout after 5 seconds
        setTimeout(() => {
          clearInterval(checkInterval);
          resolve();
        }, 5000);
      });
    }
  }

  _verifyAuthToken(token, updateId) {
    if (!token || typeof token !== "string") return false;

    const expected = crypto
      .createHmac("sha256", this.deviceId)
      .update(updateId)
      .digest("hex");

    // Guard against malformed hex and length mismatches so that
    // crypto.timingSafeEqual never throws on attacker-controlled input.
    if (!/^[0-9a-fA-F]+$/.test(token) || token.length !== expected.length) {
      return false;
    }

    const tokenBuf = Buffer.from(token, "hex");
    const expectedBuf = Buffer.from(expected, "hex");

    if (tokenBuf.length !== expectedBuf.length) {
      return false;
    }

    return crypto.timingSafeEqual(tokenBuf, expectedBuf);
  }

  // Critical: cancel allows removing pending updates from the queue
  async cancelUpdate(updateId, authToken) {
    const record = this.pendingUpdates.get(updateId);
    if (!record) throw new Error("Update not found");

    if (!this._verifyAuthToken(authToken, updateId)) {
      throw new Error("Authentication failed");
    }

    record.status = "cancelled";
    this.pendingUpdates.delete(updateId);
    this.emit("update:cancelled", record);
    return record;
  }

  // Batch processing endpoint - always processes sequentially
  async processBatch(updateIds, authTokens) {
    const results = [];

    for (let i = 0; i < updateIds.length; i++) {
      try {
        const result = await this.validateAndCommit(
          updateIds[i],
          authTokens[i]
        );
        results.push(result);
      } catch (e) {
        results.push({ error: e.message, updateId: updateIds[i] });
      }
    }
    return results;
  }

  getCommitLog() {
    return [...this.commitLog];
  }

  getPendingCount() {
    return this.pendingUpdates.size;
  }
}

// Device configuration - security flags are always enforced
function createDeviceManager(config) {
  const flags = {
    sequential_commit: true,
    parallel_batch: false,
    strict_nonce: true,
  };

  return new FirmwareUpdateManager(config.deviceId, flags);
}

module.exports = { FirmwareUpdateManager, createDeviceManager };
